30: /// <summary>
31: /// Impersonate a Windows Account
32: /// </summary>
33: /// <remarks>
34: /// <para>
35: /// This <see cref="SecurityContext"/> impersonates a Windows account.
36: /// </para>
37: /// <para>
38: /// How the impersonation is done depends on the value of <see cref="Impersonate"/>.
39: /// This allows the context to either impersonate a set of user credentials specified 
40: /// using username, domain name and password or to revert to the process credentials.
41: /// </para>
42: /// </remarks>
43: public class WindowsSecurityContext : Core.SecurityContext, IOptionHandler
44: {
45:   /// <summary>
46:   /// The impersonation modes for the <see cref="WindowsSecurityContext"/>
47:   /// </summary>
48:   /// <remarks>
49:   /// <para>
50:   /// See the <see cref="Credentials"/> property for
51:   /// details.
52:   /// </para>
53:   /// </remarks>
54:   public enum ImpersonationMode
55:   {
56:     /// <summary>
57:     /// Impersonate a user using the credentials supplied
58:     /// </summary>
59:     User,
60: 
61:     /// <summary>
62:     /// Revert this the thread to the credentials of the process
63:     /// </summary>
64:     Process
65:   }
66: 
67:   private string? _password;
68:   private WindowsIdentity? _identity;
69: 
70:   /// <summary>
71:   /// Gets or sets the impersonation mode for this security context
72:   /// </summary>
73:   /// <value>
74:   /// The impersonation mode for this security context
75:   /// </value>
76:   /// <remarks>
77:   /// <para>
78:   /// Impersonate either a user with user credentials or
79:   /// revert this thread to the credentials of the process.
80:   /// The value is one of the <see cref="ImpersonationMode"/>
81:   /// enum.
82:   /// </para>
83:   /// <para>
84:   /// The default value is <see cref="ImpersonationMode.User"/>
85:   /// </para>
86:   /// <para>
87:   /// When the mode is set to <see cref="ImpersonationMode.User"/>
88:   /// the user's credentials are established using the
89:   /// <see cref="UserName"/>, <see cref="DomainName"/> and <see cref="Password"/>
90:   /// values.
91:   /// </para>
92:   /// <para>
93:   /// When the mode is set to <see cref="ImpersonationMode.Process"/>
94:   /// no other properties need to be set. If the calling thread is 
95:   /// impersonating then it will be reverted back to the process credentials.
96:   /// </para>
97:   /// </remarks>
98:   public ImpersonationMode Credentials { get; set; } = ImpersonationMode.User;
99: 
100:   /// <summary>
101:   /// Gets or sets the Windows username for this security context
102:   /// </summary>
103:   /// <value>
104:   /// The Windows username for this security context
105:   /// </value>
106:   /// <remarks>
107:   /// <para>
108:   /// This property must be set if <see cref="Credentials"/>
109:   /// is set to <see cref="ImpersonationMode.User"/> (the default setting).
110:   /// </para>
111:   /// </remarks>
112:   public string? UserName { get; set; }
113: 
114:   /// <summary>
115:   /// Gets or sets the Windows domain name for this security context
116:   /// </summary>
117:   /// <value>
118:   /// The Windows domain name for this security context
119:   /// </value>
120:   /// <remarks>
121:   /// <para>
122:   /// The default value for <see cref="DomainName"/> is the local machine name
123:   /// taken from the <see cref="Environment.MachineName"/> property.
124:   /// </para>
125:   /// <para>
126:   /// This property must be set if <see cref="Credentials"/>
127:   /// is set to <see cref="ImpersonationMode.User"/> (the default setting).
128:   /// </para>
129:   /// </remarks>
130:   public string DomainName { get; set; } = Environment.MachineName;
131: 
132:   /// <summary>
133:   /// Sets the password for the Windows account specified by the <see cref="UserName"/> and <see cref="DomainName"/> properties.
134:   /// </summary>
135:   /// <value>
136:   /// The password for the Windows account specified by the <see cref="UserName"/> and <see cref="DomainName"/> properties.
137:   /// </value>
138:   /// <remarks>
139:   /// <para>
140:   /// This property must be set if <see cref="Credentials"/>
141:   /// is set to <see cref="ImpersonationMode.User"/> (the default setting).
142:   /// </para>
143:   /// </remarks>
144:   [System.Diagnostics.CodeAnalysis.SuppressMessage("Design", "CA1044:Properties should not be write only", 
145:     Justification = "Password must be write only")]
146:   public string Password { set => _password = value; }
