148:   /// <summary>
149:   /// Initialize the SecurityContext based on the options set.
150:   /// </summary>
151:   /// <remarks>
152:   /// <para>
153:   /// This is part of the <see cref="IOptionHandler"/> delayed object
154:   /// activation scheme. The <see cref="ActivateOptions"/> method must 
155:   /// be called on this object after the configuration properties have
156:   /// been set. Until <see cref="ActivateOptions"/> is called this
157:   /// object is in an undefined state and must not be used. 
158:   /// </para>
159:   /// <para>
160:   /// If any of the configuration properties are modified then 
161:   /// <see cref="ActivateOptions"/> must be called again.
162:   /// </para>
163:   /// <para>
164:   /// The security context will try to Logon the specified user account and
165:   /// capture a primary token for impersonation.
166:   /// </para>
167:   /// </remarks>
168:   /// <exception cref="ArgumentNullException">The required <see cref="UserName" />, 
169:   /// <see cref="DomainName" /> or <see cref="Password" /> properties were not specified.</exception>
170:   public void ActivateOptions()
171:   {
172:     if (Credentials == ImpersonationMode.User)
173:     {
174:       _identity = LogonUser(UserName.EnsureNotNull(), DomainName.EnsureNotNull(), _password.EnsureNotNull());
175:     }
176:   }
177: 
178:   /// <summary>
179:   /// Impersonate the Windows account specified by the <see cref="UserName"/> and <see cref="DomainName"/> properties.
180:   /// </summary>
181:   /// <param name="state">caller provided state</param>
182:   /// <returns>
183:   /// An <see cref="IDisposable"/> instance that will revoke the impersonation of this SecurityContext
184:   /// </returns>
185:   /// <remarks>
186:   /// <para>
187:   /// Depending on the <see cref="Credentials"/> property either
188:   /// impersonate a user using credentials supplied or revert 
189:   /// to the process credentials.
190:   /// </para>
191:   /// </remarks>
192:   public override IDisposable? Impersonate(object state)
193:   {
194:     if (Credentials == ImpersonationMode.User)
195:     {
196:       if (_identity is not null)
197:       {
198:         return new DisposableImpersonationContext(_identity.Impersonate());
199:       }
200:     }
201:     else if (Credentials == ImpersonationMode.Process)
202:     {
203:       // Impersonate(0) will revert to the process credentials
204:       return new DisposableImpersonationContext(WindowsIdentity.Impersonate(IntPtr.Zero));
205:     }
206:     return null;
207:   }
208: 
209:   /// <summary>
210:   /// Create a <see cref="WindowsIdentity"/> given the userName, domainName and password.
211:   /// </summary>
212:   /// <param name="userName">the user name</param>
213:   /// <param name="domainName">the domain name</param>
214:   /// <param name="password">the password</param>
215:   /// <returns>the <see cref="WindowsIdentity"/> for the account specified</returns>
216:   /// <remarks>
217:   /// <para>
218:   /// Uses the Windows API call LogonUser to get a principal token for the account. This
219:   /// token is used to initialize the WindowsIdentity.
220:   /// </para>
221:   /// </remarks>
222:   [SecuritySafeCritical]
223:   [System.Security.Permissions.SecurityPermission(System.Security.Permissions.SecurityAction.Demand, UnmanagedCode = true)]
224:   private static WindowsIdentity LogonUser(string userName, string domainName, string password)
225:   {
226:     const int logon32ProviderDefault = 0;
227:     //This parameter causes LogonUser to create a primary token.
228:     const int logon32LogonInteractive = 2;
229: 
230:     // Call LogonUser to obtain a handle to an access token.
231:     IntPtr tokenHandle = IntPtr.Zero;
232:     if (!NativeMethods.LogonUser(userName, domainName, password, logon32LogonInteractive, logon32ProviderDefault, ref tokenHandle))
233:     {
234:       NativeError error = NativeError.GetLastError();
235:       throw new SecurityException($"Failed to LogonUser [{userName}] in Domain [{domainName}]. Error: {error}");
236:     }
237: 
238:     const int securityImpersonation = 2;
239:     IntPtr dupeTokenHandle = IntPtr.Zero;
240:     if (!NativeMethods.DuplicateToken(tokenHandle, securityImpersonation, ref dupeTokenHandle))
241:     {
242:       NativeError error = NativeError.GetLastError();
243:       if (tokenHandle != IntPtr.Zero)
244:       {
245:         NativeMethods.CloseHandle(tokenHandle);
246:       }
247:       throw new SecurityException($"Failed to DuplicateToken after LogonUser. Error: {error}");
248:     }
249: 
250:     WindowsIdentity identity = new(dupeTokenHandle);
251: 
252:     // Free the tokens.
253:     if (dupeTokenHandle != IntPtr.Zero)
254:     {
255:       NativeMethods.CloseHandle(dupeTokenHandle);
256:     }
257:     if (tokenHandle != IntPtr.Zero)
258:     {
259:       NativeMethods.CloseHandle(tokenHandle);
260:     }
261: 
262:     return identity;
263:   }
264: 
265:   /// <summary>
266:   /// Adds <see cref="IDisposable"/> to <see cref="WindowsImpersonationContext"/>
267:   /// </summary>
268:   /// <param name="impersonationContext">the impersonation context being wrapped</param>
269:   /// <remarks>
270:   /// <para>
271:   /// Helper class to expose the <see cref="WindowsImpersonationContext"/>
272:   /// through the <see cref="IDisposable"/> interface.
273:   /// </para>
274:   /// </remarks>
275:   private sealed class DisposableImpersonationContext(WindowsImpersonationContext impersonationContext) : IDisposable
276:   {
277:     /// <summary>
278:     /// Revert the impersonation
279:     /// </summary>
280:     public void Dispose() => impersonationContext.Undo();
281:   }
282: }
