163:   /// <summary>
164:   /// Gets the host name or machine name for the current machine.
165:   /// </summary>
166:   /// <remarks>
167:   /// <para>
168:   /// The host name (<see cref="System.Net.Dns.GetHostName"/>) or
169:   /// the machine name (<see cref="Environment.MachineName"/>) for
170:   /// the current machine, or if neither of these are available
171:   /// then <c>NOT AVAILABLE</c> is returned.
172:   /// </para>
173:   /// </remarks>
174:   public static string HostName
175:   {
176:     get
177:     {
178:       if (_sHostName is null)
179:       {
180:         // Get the DNS host name of the current machine
181:         try
182:         {
183:           // Lookup the host name
184:           _sHostName = System.Net.Dns.GetHostName();
185:         }
186:         catch (System.Net.Sockets.SocketException)
187:         {
188:           LogLog.Debug(_declaringType, "Socket exception occurred while getting the dns hostname. Error Ignored.");
189:         }
190:         catch (System.Security.SecurityException)
191:         {
192:           // We may get a security exception looking up the hostname
193:           // You must have Unrestricted DnsPermission to access resource
194:           LogLog.Debug(_declaringType, "Security exception occurred while getting the dns hostname. Error Ignored.");
195:         }
196:         catch (Exception e) when (!e.IsFatal())
197:         {
198:           LogLog.Debug(_declaringType, "Some other exception occurred while getting the dns hostname. Error Ignored.", e);
199:         }
200: 
201:         // Get the NETBIOS machine name of the current machine
202:         if (string.IsNullOrEmpty(_sHostName))
203:         {
204:           try
205:           {
206:             _sHostName = Environment.MachineName;
207:           }
208:           catch (InvalidOperationException)
209:           {
210:           }
211:           catch (System.Security.SecurityException)
212:           {
213:             // We may get a security exception looking up the machine name
214:             // You must have Unrestricted EnvironmentPermission to access resource
215:           }
216:         }
217: 
218:         // Couldn't find a value
219:         if (string.IsNullOrEmpty(_sHostName))
220:         {
221:           _sHostName = NotAvailableText;
222:           LogLog.Debug(_declaringType, "Could not determine the hostname. Error Ignored. Empty host name will be used");
223:         }
224:       }
225:       return _sHostName!;
226:     }
227:   }
