333:   /// <summary>
334:   /// Gets the assembly location path for the specified assembly.
335:   /// </summary>
336:   /// <param name="myAssembly">The assembly to get the location for.</param>
337:   /// <returns>The location of the assembly.</returns>
338:   /// <remarks>
339:   /// <para>
340:   /// This method does not guarantee to return the correct path
341:   /// to the assembly. If only tries to give an indication as to
342:   /// where the assembly was loaded from.
343:   /// </para>
344:   /// </remarks>
345:   public static string AssemblyLocationInfo(Assembly myAssembly)
346:   {
347:     if (myAssembly.EnsureNotNull().GlobalAssemblyCache)
348:     {
349:       return "Global Assembly Cache";
350:     }
351:     try
352:     {
353:       if (myAssembly.IsDynamic)
354:       {
355:         return "Dynamic Assembly";
356:       }
357: 
358:       if (myAssembly.GetType().FullName == "System.Reflection.Emit.InternalAssemblyBuilder")
359:       {
360:         return "Dynamic Assembly";
361:       }
362: 
363:       // This call requires FileIOPermission for access to the path
364:       // if we don't have permission then we just ignore it and
365:       // carry on.
366:       return myAssembly.Location;
367:     }
368:     catch (NotSupportedException)
369:     {
370:       // The location information may be unavailable for dynamic assemblies and a NotSupportedException
371:       // is thrown in those cases. See: http://msdn.microsoft.com/de-de/library/system.reflection.assembly.location.aspx
372:       return "Dynamic Assembly";
373:     }
374:     catch (TargetInvocationException ex)
375:     {
376:       return $"Location Detect Failed ({ex.Message})";
377:     }
378:     catch (ArgumentException ex)
379:     {
380:       return $"Location Detect Failed ({ex.Message})";
381:     }
382:     catch (System.Security.SecurityException)
383:     {
384:       return "Location Permission Denied";
385:     }
386:   }
