396:   /// without the version, culture, or public key. i.e. it is just the 
397:   /// assembly's file name without the extension.
398:   /// </para>
399:   /// <para>
400:   /// Because of a FileIOPermission security demand we cannot do
401:   /// the obvious Assembly.GetName().Name. We are allowed to get
402:   /// the <see cref="Assembly.FullName" /> of the assembly so we 
403:   /// start from there and strip out just the assembly name.
404:   /// </para>
405:   /// </remarks>
406:   public static string AssemblyShortName(Assembly myAssembly)
407:   {
408:     string name = myAssembly.EnsureNotNull().FullName ?? string.Empty;
409:     int offset = name.IndexOf(',');
410:     if (offset > 0)
411:     {
412:       name = name.Substring(0, offset);
413:     }
414:     return name.Trim();
415:   }
