475:   /// <summary>
476:   /// Loads the type specified in the type string.
477:   /// </summary>
478:   /// <param name="relativeAssembly">An assembly to load the type from.</param>
479:   /// <param name="typeName">The name of the type to load.</param>
480:   /// <param name="throwOnError">Flag set to <see langword="true"/> to throw an exception if the type cannot be loaded.</param>
481:   /// <param name="ignoreCase"><see langword="true"/> to ignore the case of the type name; otherwise, <see langword="false"/></param>
482:   /// <returns>The type loaded or <see langword="null"/> if it could not be loaded.</returns>
483:   /// <remarks>
484:   /// <para>
485:   /// If the type name is fully qualified, i.e. if contains an assembly name in 
486:   /// the type name, the type will be loaded from the system using 
487:   /// <see cref="Type.GetType(string,bool)"/>.
488:   /// </para>
489:   /// <para>
490:   /// If the type name is not fully qualified it will be loaded from the specified
491:   /// assembly. If the type is not found in the assembly then all the loaded assemblies 
492:   /// will be searched for the type.
493:   /// </para>
494:   /// </remarks>
495:   public static Type? GetTypeFromString(Assembly relativeAssembly, string typeName, bool throwOnError, bool ignoreCase)
496:   {
497:     // Check if the type name specifies the assembly name
498:     if (typeName.EnsureNotNull().IndexOf(',') == -1)
499:     {
500:       // Attempt to look up the type from the relativeAssembly
501:       if (relativeAssembly.EnsureNotNull().GetType(typeName, false, ignoreCase) is Type type)
502:       {
503:         return type;
504:       }
505: 
506:       Assembly[]? loadedAssemblies = null;
507:       try
508:       {
509:         loadedAssemblies = AppDomain.CurrentDomain.GetAssemblies();
510:       }
511:       catch (System.Security.SecurityException)
512:       {
513:         // Insufficient permissions to get the list of loaded assemblies
514:       }
515: 
516:       if (loadedAssemblies is not null)
517:       {
518:         Type? fallback = null;
519:         // Search the loaded assemblies for the type
520:         foreach (Assembly assembly in loadedAssemblies)
521:         {
522:           if (assembly.GetType(typeName, false, ignoreCase) is Type t)
523:           {
524:             // Found type in loaded assembly
525:             LogLog.Debug(_declaringType, $"Loaded type [{typeName}] from assembly [{assembly.FullName}] by searching loaded assemblies.");
526:             if (assembly.GlobalAssemblyCache)
527:             {
528:               fallback = t;
529:             }
530:             else
531:             {
532:               return t;
533:             }
534:           }
535:         }
536:         if (fallback is not null)
537:         {
538:           return fallback;
539:         }
540:       }
541: 
542:       // Didn't find the type
543:       if (throwOnError)
544:       {
545:         throw new TypeLoadException($"Could not load type [{typeName}]. Tried assembly [{relativeAssembly.FullName}] and all loaded assemblies");
546:       }
547:       return null;
548:     }
549: 
550:     // Includes explicit assembly name
551:     return Type.GetType(typeName, throwOnError, ignoreCase);
552:   }
