577:   /// </summary>
578:   /// <param name="s">the string to parse</param>
579:   /// <param name="val">out param where the parsed value is placed</param>
580:   /// <returns><see langword="true"/> if the string was parsed into an integer</returns>
581:   /// <remarks>
582:   /// <para>
583:   /// Attempts to parse the string into an integer. If the string cannot
584:   /// be parsed then this method returns <see langword="false"/>. The method does not throw an exception.
585:   /// </para>
586:   /// </remarks>
587:   public static bool TryParse(string s, out int val)
588:   {
589:     val = 0;
590: 
591:     try
592:     {
593:       if (double.TryParse(s, System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out double doubleVal))
594:       {
595:         val = Convert.ToInt32(doubleVal);
596:         return true;
597:       }
598:     }
599:     catch (Exception e) when (!e.IsFatal())
600:     {
601:       // Ignore exception, just return false
602:     }
603: 
604:     return false;
605:   }
