693:   /// Convert a path into a fully qualified local file path.
694:   /// </summary>
695:   /// <param name="path">The path to convert.</param>
696:   /// <returns>The fully qualified path.</returns>
697:   /// <remarks>
698:   /// <para>
699:   /// Converts the path specified to a fully
700:   /// qualified path. If the path is relative it is
701:   /// taken as relative from the application base 
702:   /// directory.
703:   /// </para>
704:   /// <para>
705:   /// The path specified must be a local file path, a URI is not supported.
706:   /// </para>
707:   /// </remarks>
708:   public static string ConvertToFullPath(string path)
709:   {
710:     path.EnsureNotNull();
711: 
712:     string baseDirectory = string.Empty;
713:     try
714:     {
715:       string applicationBaseDirectory = ApplicationBaseDirectory;
716: 
717:       // applicationBaseDirectory may be a URI not a local file path
718:       Uri applicationBaseDirectoryUri = new(applicationBaseDirectory);
719:       if (applicationBaseDirectoryUri.IsFile)
720:       {
721:         baseDirectory = applicationBaseDirectoryUri.LocalPath;
