  /// <param name="s">the string to parse</param>
  /// <param name="val">out param where the parsed value is placed</param>
  /// <returns><see langword="true"/> if the string was parsed into an integer</returns>
  /// <remarks>
  /// <para>
  /// Attempts to parse the string into an integer. If the string cannot
  /// be parsed then this method returns <see langword="false"/>. The method does not throw an exception.
  /// </para>
  /// </remarks>
  public static bool TryParse(string s, out int val)
  {
    val = 0;

    try
    {
      if (double.TryParse(s, System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out double doubleVal))
      {
        val = Convert.ToInt32(doubleVal);
        return true;
      }
    }
    catch (Exception e) when (!e.IsFatal())
    {
      // Ignore exception, just return false
    }

    return false;
  }

